abstract class Payment {}
class CreditCardPayment extends Payment {}
class PaypalPayment extends Payment {}

abstract class Processor {}
class CreditCardProcessor extends Processor {}
class PaypalProcessor extends Processor {}

// Version A: two mirrored hierarchies
abstract class Report {}
class SalesReport extends Report {}
class InventoryReport extends Report {}

abstract class Exporter {}
class SalesExporter extends Exporter {}
class InventoryExporter extends Exporter {}

// Version B: single hierarchy with composition
abstract class ReportV2 { constructor(public exporter: ExporterV2) {} }
class SalesReportV2 extends ReportV2 {}
class InventoryReportV2 extends ReportV2 {}

interface ExporterV2 { export(r: ReportV2): string }
class CsvExporter implements ExporterV2 { export(r: ReportV2){ return 'csv' } }
class JsonExporter implements ExporterV2 { export(r: ReportV2){ return 'json' } }
